"""
# As amlodipine besylate is a drug, the corresponding information can be found in the prescriptions database.
prescriptions_db = LoadDB('prescriptions')
filtered_prescriptions_db = FilterDB(prescriptions_db, 'DRUG=amlodipine besylate||STARTDATE like 2105%')
hadm_id_list = GetValue(filtered_prescriptions_db, 'HADM_ID, list')

# The HADM_ID can be used to find the corresponding DRUG in the prescriptions database.
drug_frequency = {}
for hadm_id in hadm_id_list:
    filtered_prescriptions_db = FilterDB(prescriptions_db, 'HADM_ID={}'.format(hadm_id))
    drug_list = GetValue(filtered_prescriptions_db, 'DRUG, list')
    for drug in drug_list:
        if drug in drug_frequency:
            drug_frequency[drug] += 1
        else:
            drug_frequency[drug] = 1

# We can then count the frequency of each drug and find the top three frequently prescribed drugs.
top_three_drugs = sorted(drug_frequency, key=drug_frequency.get, reverse=True)[:3]
answer = top_three_drugs
answer
